/**
 * Build-time icon resolver. Turns an icon reference as written in Markdown
 * (`rocket`, `fa-brands fa-github`, `lucide:rocket`, an emoji, a URL, inline
 * `<svg>`) into inline markup, so pages never fetch icons from a CDN at view
 * time and offline (file://) builds render every icon.
 *
 * Data lives in src/icons/{lucide,fa}.json (generated by scripts/build-icons.js
 * from the pinned lucide-static (ISC) and @fortawesome/fontawesome-free
 * (icons CC BY 4.0) devDependencies). Files are read lazily and only when an
 * icon is actually used, so sites without icons pay nothing.
 */
import fs from 'fs';

let _lucide;
let _fa;
let _names;

function loadJson(file) {
  return JSON.parse(fs.readFileSync(new URL(`./icons/${file}`, import.meta.url), 'utf8'));
}
const lucide = () => (_lucide ||= loadJson('lucide.json'));
const fa = () => (_fa ||= loadJson('fa.json'));

// Legacy docslit built-in names that are not Lucide names.
const LEGACY = { warning: 'triangle-alert', error: 'circle-x' };
// Names the original 33 built-in icons used; with library "auto" they keep the Lucide look.
const LEGACY_BUILTIN = new Set(['check', 'x', 'warning', 'info', 'error', 'arrow-right', 'arrow-left', 'arrow-up', 'arrow-down',
  'chevron-right', 'chevron-down', 'external-link', 'link', 'copy', 'download', 'code', 'terminal', 'file', 'folder', 'search',
  'star', 'zap', 'book', 'settings', 'user', 'home', 'grid', 'list', 'eye', 'lock', 'package', 'globe', 'cpu']);

let _config = null;
/** Optional site-level config: `{ library: 'auto' | 'fontawesome' | 'lucide' }`. */
export function setIconConfig(cfg) { _config = cfg && typeof cfg === 'object' ? { ...cfg } : null; }
export function getIconConfig() {
  if (_config) return _config;
  try {
    const raw = JSON.parse(fs.readFileSync(`${process.cwd()}/docslit.json`, 'utf8'));
    _config = raw && raw.icons && typeof raw.icons === 'object' ? { ...raw.icons } : {};
  } catch { _config = {}; }
  return _config;
}

const FA_STYLE_WORDS = {
  'fa-solid': 'solid', fas: 'solid', fa: 'solid',
  'fa-regular': 'regular', far: 'regular',
  'fa-brands': 'brands', fab: 'brands',
  'fa-light': 'solid', fal: 'solid', 'fa-thin': 'solid', fat: 'solid',
  'fa-duotone': 'solid', fad: 'solid', 'fa-sharp': 'solid', fass: 'solid',
};
const ICON_TYPE = { regular: 'regular', brands: 'brands', solid: 'solid' };
const FA_MODS = /^fa-(?:xs|sm|lg|xl|2xs|2xl|[1-9]x|10x|fw|spin|pulse|beat|fade|bounce|flip|shake|spin-pulse|spin-reverse|rotate-\d+|flip-(?:horizontal|vertical|both)|inverse|border|pull-(?:left|right)|stack|ul|li|sharp-.*)$/;

const SVG_ATTRS = 'aria-hidden="true" focusable="false"';

function lucideSvg(name) {
  const l = lucide();
  const key = l.icons[name] ? name : l.aliases[name];
  const inner = key && l.icons[key];
  if (!inner) return null;
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ${SVG_ATTRS}>${inner}</svg>`;
}

function faSvg(name, style) {
  const f = fa();
  const real = (set) => (f[set][name] ? name : f.aliases[name] && f[set][f.aliases[name]] ? f.aliases[name] : null);
  let set = style || null;
  let key = set ? real(set) : null;
  if (!key) {
    for (const s of set === 'regular' ? ['regular', 'solid', 'brands'] : ['solid', 'brands', 'regular']) {
      key = real(s);
      if (key) { set = s; break; }
    }
  }
  if (!key) return null;
  const [w, d] = f[set][key];
  return `<svg viewBox="0 0 ${w} 512" fill="currentColor" ${SVG_ATTRS}><path d="${d}"/></svg>`;
}

/** Strip scripts / event handlers from author-supplied inline SVG. */
export function sanitizeSvg(svg) {
  return String(svg)
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
    .replace(/\s(?:xlink:)?href\s*=\s*("\s*javascript:[^"]*"|'\s*javascript:[^']*')/gi, '');
}

const EMOJI_RE = /^[\p{Extended_Pictographic}\p{Regional_Indicator}‍️⃣\s]+$/u;
const URL_RE = /^(?:https?:)?\/\/|^data:image\/|^\.{0,2}\/|\.(?:svg|png|jpe?g|webp|gif|avif|ico)(?:[?#].*)?$/i;

/**
 * Classify + resolve an icon reference.
 * @returns {{kind:'svg',svg:string,name:string,source:string}
 *   |{kind:'emoji',text:string}|{kind:'img',src:string}|{kind:'unknown',name:string,suggestion:string|null}
 *   |{kind:'none'}}
 */
export function resolveIcon(raw, { iconType, library } = {}) {
  const value = String(raw ?? '').trim();
  if (!value || value === 'none' || value === 'false') return { kind: 'none' };
  if (/^<svg[\s>]/i.test(value)) return { kind: 'svg', svg: sanitizeSvg(value), name: 'inline', source: 'inline' };
  if (EMOJI_RE.test(value)) return { kind: 'emoji', text: value };
  if (URL_RE.test(value) && !/^[a-z0-9][a-z0-9-]*$/i.test(value)) return { kind: 'img', src: value };

  const lib = library || getIconConfig().library || 'auto';
  let style = ICON_TYPE[String(iconType || '').toLowerCase()] || (iconType ? 'solid' : null);
  let slug = '';
  let forced = null; // 'lucide' | 'fa'
  const parts = value.split(/\s+/);
  const prefixed = /^(lucide|fa|fontawesome|tabler):/i.exec(value);
  if (prefixed) {
    forced = prefixed[1].toLowerCase() === 'lucide' ? 'lucide' : 'fa';
    slug = value.slice(prefixed[0].length).trim();
  } else {
    for (const p of parts) {
      if (FA_STYLE_WORDS[p]) { style = FA_STYLE_WORDS[p]; forced = 'fa'; continue; }
      if (FA_MODS.test(p)) continue;
      if (p.startsWith('fa-')) { slug = p.slice(3); forced = 'fa'; } else if (!slug) slug = p;
    }
  }
  slug = slug.toLowerCase().replace(/_/g, '-');
  if (!slug) return { kind: 'none' };

  const tryLucide = () => { const s = lucideSvg(LEGACY[slug] || slug); return s ? { kind: 'svg', svg: s, name: slug, source: 'lucide' } : null; };
  const tryFa = () => { const s = faSvg(slug, style); return s ? { kind: 'svg', svg: s, name: slug, source: `fa-${style || 'solid'}` } : null; };

  let order;
  if (forced === 'fa') order = [tryFa, tryLucide];
  else if (forced === 'lucide') order = [tryLucide, tryFa];
  else if (lib === 'lucide') order = [tryLucide, tryFa];
  else if (lib === 'fontawesome') order = [tryFa, tryLucide];
  else order = LEGACY_BUILTIN.has(slug) ? [tryLucide, tryFa] : [tryFa, tryLucide]; // 'auto'
  for (const t of order) {
    const r = t();
    if (r) return r;
  }
  return { kind: 'unknown', name: slug, suggestion: suggestIcon(slug) };
}

/** Convenience: inline `<svg>` markup for a name, or '' when it can't be resolved to an SVG. */
export function renderIconSvg(raw, opts) {
  const r = resolveIcon(raw, opts);
  return r.kind === 'svg' ? r.svg : '';
}

/** Every known icon name (Lucide + Font Awesome Free, canonical and aliases). */
export function listIconNames() {
  if (!_names) {
    const l = lucide();
    const f = fa();
    _names = [...new Set([
      ...Object.keys(l.icons), ...Object.keys(l.aliases),
      ...Object.keys(f.solid), ...Object.keys(f.regular), ...Object.keys(f.brands), ...Object.keys(f.aliases),
    ])].sort();
  }
  return _names;
}

export function editDistance(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[b.length];
}

/** Nearest known icon name, or null when nothing is plausibly close. */
export function suggestIcon(name) {
  const n = String(name).toLowerCase();
  let best = null;
  let bestD = Infinity;
  for (const c of listIconNames()) {
    if (Math.abs(c.length - n.length) > 4) continue;
    let d = editDistance(n, c);
    if (c.startsWith(n) || n.startsWith(c)) d = Math.min(d, 1.5);
    if (d < bestD) { bestD = d; best = c; }
  }
  return best !== null && bestD <= Math.max(2, Math.floor(n.length / 3)) ? best : null;
}

/** Icon reference attributes found in a Markdown source: [{ tag, attr, value, iconType, line }]. */
export function findIconRefs(markdown) {
  const out = [];
  const src = String(markdown || '').replace(/```[\s\S]*?```/g, (m) => m.replace(/[^\n]/g, ' ')).replace(/`[^`\n]*`/g, (m) => ' '.repeat(m.length));
  const tagRe = /<(wc-[a-z0-9-]+|[A-Z][A-Za-z0-9.]*)((?:\s+[^<>]*?)?)\/?>/g;
  let m;
  while ((m = tagRe.exec(src))) {
    const attrs = m[2] || '';
    const type = /\s(?:icon-type|iconType)\s*=\s*"([^"]*)"/.exec(attrs)?.[1];
    const re = /\s(icon|icon-name|right-icon|iconName)\s*=\s*"([^"]*)"/g;
    let a;
    while ((a = re.exec(attrs))) {
      out.push({ tag: m[1], attr: a[1], value: a[2], iconType: type, line: src.slice(0, m.index).split('\n').length });
    }
    if (m[1] === 'wc-icon') {
      const n = /\sname\s*=\s*"([^"]*)"/.exec(attrs);
      if (n) out.push({ tag: m[1], attr: 'name', value: n[1], iconType: type, line: src.slice(0, m.index).split('\n').length });
    }
  }
  return out;
}

/** Unknown-icon diagnostics for a Markdown source. */
export function checkIcons(markdown) {
  const issues = [];
  const seen = new Set();
  for (const ref of findIconRefs(markdown)) {
    const r = resolveIcon(ref.value, { iconType: ref.iconType });
    if (r.kind !== 'unknown') continue;
    const key = `${ref.line}:${ref.value}`;
    if (seen.has(key)) continue;
    seen.add(key);
    issues.push({
      ...ref,
      message: `Unknown icon "${ref.value}" on <${ref.tag}>${r.suggestion ? `. Did you mean "${r.suggestion}"?` : ''}`,
      suggestion: r.suggestion,
    });
  }
  return issues;
}
